static void __stdcall INV_FormatBlockChanceText(uint16_t * wszText, D2ItemsTxt * pItemsTxt, D2UnitStrc * pUnit) {
    D2SkillStrc* pSkill;
    eD2States eHolyShieldState;
    int nClassIdOrLevel;
    int32_t nHolyShieldBonus;
    uint16_t wszLineBuffer[256];
    char szNumBuffer[32];
    uint16_t wszNumBuffer[32];
    int nBlockChance;
    nBlockChance = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_toblock, 0);
    D2UnitStrc* pPlayerUnit_lcl;
    pPlayerUnit_lcl = UNIT::Player::GetPlayerUnit_UI();
    if (pPlayerUnit_lcl) {
      D2CharStatsTxt* pCharStats;
      nClassIdOrLevel = pPlayerUnit_lcl->nClassId;
      if (nClassIdOrLevel < 0 || nClassIdOrLevel >= sgptDataTable->nTxtCharStatsSize) {
        pCharStats = 0;
      } else {
        pCharStats = sgptDataTable->pTxtCharStats + nClassIdOrLevel;
      }

      nBlockChance += (uint32_t)pCharStats->BlockFactor;
      pSkill = D2Common::Skills::SKILLS_GetSkillByEnum(pPlayerUnit_lcl, SKILL_HolyShield);
      if (pSkill) {
        eHolyShieldState = D2Common::DATATBLS::ItemStats::UNIT_GetUnitState(pPlayerUnit_lcl, STATE_holyshield);
        if (eHolyShieldState != STATE_none) {
          nClassIdOrLevel = D2Common::Skills::GetSkillLevel(pPlayerUnit_lcl, pSkill, 1);
          nHolyShieldBonus = D2Common::Skills::SKILLS_GetParam45WithDiminishing(nClassIdOrLevel, 0x75);
          nBlockChance += nHolyShieldBonus;
        }
      }
      if (nBlockChance > 0x4b) {
        nBlockChance = 0x4b;
        goto format_block_chance;
      }
    }
    if (!nBlockChance) {
      return;
    }

    format_block_chance:
    wszNumBuffer[0] = L'\0';
    for (int iFill = 1; iFill < 32; iFill++) {
      wszNumBuffer[iFill] = L'\0';
    }

    for (nClassIdOrLevel = 0; nClassIdOrLevel < 0x100; nClassIdOrLevel++) {
      wszLineBuffer[nClassIdOrLevel] = L'\0';
    }

    Storm::Source::SSTR::SStrPrintf(szNumBuffer, 0x20, "%d%%\n", nBlockChance);
    D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(wszNumBuffer, szNumBuffer, 0x20);
    if (nBlockChance > (int)(uint32_t)(uint8_t)pItemsTxt->bBlock) {
      ui::AppendAsWideChar(wszNumBuffer, 3);
    }

    uint16_t* pwTmp = D2Lang::StrTable::strtable::GetLocaleString(0x2b0a);
    D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszLineBuffer, pwTmp);
    ui::AppendAsWideChar(wszLineBuffer, 0);
    D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszText, wszLineBuffer);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, wszNumBuffer);
}

// Formats defense range text for shields and boots, displaying min-max defense values. For shields, checks if Holy Shield skill is active and adds its defense bonus to both min and max values before formatting the output string.
static void __stdcall INV_FormatDefenseRangeText(D2UnitStrc * pUnit, D2ItemsTxt * pStatRecord, uint16_t * wszText) {
    D2SkillStrc* pSkill;
    eD2States iStateCheck;
    int nSkillLevel;
    int32_t nSkillDmgCalc;
    uint16_t wszTempConversionBuffer[10];
    char szPrintfBuffer[12];
    memset(wszTempConversionBuffer, 0, 10 * sizeof(wszTempConversionBuffer[0]));
    uint16_t* pwSeparator = D2Lang::StrTable::strtable::GetLocaleString(0xf9b);
    uint16_t* pwColorSuffix = D2Lang::StrTable::strtable::GetLocaleString(0xf9e);
    D2ItemsTxt* nMinDefense = (D2ItemsTxt*)(uint32_t)pStatRecord->nMinDam;
    uint32_t nMaxDefense = (uint32_t)pStatRecord->nMaxDam;
    uint32_t nTypeCheck = D2Common::ITEMS::Items::ITEMS_IsA(pUnit, ITEMTYPE_AnyShield);
    int nStatRecord = (int)nMinDefense;
    if (nTypeCheck) {
      D2UnitStrc* pPlayerUnit_lcl;
      *(uint16_t*)(char*)&pUnit = 0xd8c;
      pPlayerUnit_lcl = UNIT::Player::GetPlayerUnit_Net();
      pSkill = D2Common::Skills::SKILLS_GetSkillByEnum(pPlayerUnit_lcl, SKILL_HolyShield);
      if (pSkill) {
        iStateCheck = D2Common::DATATBLS::ItemStats::UNIT_GetUnitState(pPlayerUnit_lcl, STATE_holyshield);
        if (iStateCheck != STATE_none) {
          nSkillLevel = D2Common::Skills::GetSkillLevel(pPlayerUnit_lcl, pSkill, 1);
          nSkillDmgCalc = D2Common::Skills::SKILL_CalcMinDamage(pPlayerUnit_lcl, 0x75, nSkillLevel, 1);
          nStatRecord = (int)(nMinDefense->szFlippyFile + (nSkillDmgCalc >> 8));
          nSkillDmgCalc = D2Common::Skills::SKILL_CalcMaxDamage(pPlayerUnit_lcl, 0x75, nSkillLevel, 1);
          nMaxDefense += nSkillDmgCalc >> 8;
        }
      }
    } else {
      nTypeCheck = D2Common::ITEMS::Items::ITEMS_IsA(pUnit, ITEMTYPE_Boots);
      if (!nTypeCheck) {
        return;
      }

      *(uint16_t*)(char*)&pUnit = 0x5516;
    }

    uint16_t* pwString = D2Lang::StrTable::strtable::GetLocaleString((uint16_t)(uintptr_t)pUnit);
    D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszText, pwString);
    Storm::Source::SSTR::SStrPrintf(szPrintfBuffer, 10, "%i", nStatRecord);
    D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(wszTempConversionBuffer, szPrintfBuffer, 9);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, pwSeparator);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, wszTempConversionBuffer);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, pwSeparator);
    pwString = D2Lang::StrTable::strtable::GetLocaleString(0xd88);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, pwString);
    Storm::Source::SSTR::SStrPrintf(szPrintfBuffer, 10, "%i", nMaxDefense);
    D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(wszTempConversionBuffer, szPrintfBuffer, 9);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, pwSeparator);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, wszTempConversionBuffer);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, pwColorSuffix);
}

void __stdcall INV_FormatArmorClassText(D2UnitStrc * pUnit, D2UnitStrc * pUnit2, uint16_t * wszText) {
    int32_t nPercentApplied;
    uint16_t local_38[10];
    char szNumBuffer[12];
    D2UnitStrc* pEffectiveUnit = pUnit;
    if (!pUnit) {
      return;
    }

    memset(local_38, 0, 10 * sizeof(local_38[0]));
    uint16_t* pwColorPrefix = D2Lang::StrTable::strtable::GetLocaleString(0xf9b);
    uint16_t* pwColorSuffix = D2Lang::StrTable::strtable::GetLocaleString(0xf9e);
    uint32_t nPrevStatActive = 0;
    D2UnitStrc* pOwnerUnit = D2Common::Stats::StatsEx::SEVER_ITEM_GetOwner(pItemToDescribe, &nPrevStatActive);
    uint32_t nPeriodOfDay = (uint32_t)(pOwnerUnit != 0);
    if (pOwnerUnit && pEffectiveUnit != pOwnerUnit) {
      pEffectiveUnit = pOwnerUnit;
      pUnit = pOwnerUnit;
    }

    D2Common::Stats::StatsEx::STATLIST_SetItemStatActive(pEffectiveUnit, pItemToDescribe, 1);
    int32_t nArmorClass = D2Common::Stats::StatsEx::GetTxtArmorClass(pItemToDescribe);
    if (!nPeriodOfDay) {
      D2Common::Stats::StatsEx::STATLIST_RemoveFromOwnerAndRecalc(pUnit, pItemToDescribe);
    } else {
      D2Common::Stats::StatsEx::STATLIST_SetItemStatActive(pOwnerUnit, pItemToDescribe, nPrevStatActive);
    }

    pEffectiveUnit = pUnit2;
    int bIsModified = 0;
    int32_t nServerOrMod = D2Common::Stats::StatsEx::SERVER_GetUnitStat(pUnit2, UNITSTAT_armorclass, 0);
    if (nServerOrMod != nArmorClass) {
      bIsModified = 1;
    }

    uint32_t nByTimeMod = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pEffectiveUnit, UNITSTAT_item_armor_bytime, 0);
    if (nByTimeMod && sgptDataTable->nTxtItemStatCostSize > 0x10c && sgptDataTable->pTxtItemStatCost != (D2ItemStatCostTxt*)-86832 && pUnit->pDrlgAct) {
      nPeriodOfDay = 0;
      nServerOrMod = D2Common::Environment::DRLGENV_GetPeriodOfDayFromAct(pUnit->pDrlgAct, (int32_t*)&nPeriodOfDay);
      nServerOrMod = D2Common::ITEMS::ItemMods::ITEMMODS_CalculateRepairCost(nByTimeMod, nServerOrMod, nPeriodOfDay, nullptr, nullptr, nullptr);
      nArmorClass += nServerOrMod;
      if (nServerOrMod) {
        bIsModified = 1;
      }
    }

    nByTimeMod = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit2, UNITSTAT_item_armorpercent_bytime, 0);
    if (nByTimeMod && sgptDataTable->nTxtItemStatCostSize > 0x10d && sgptDataTable->pTxtItemStatCost != (D2ItemStatCostTxt*)-87156) {
      D2DrlgActStrc** ppDVar1;
      ppDVar1 = &pUnit->pDrlgAct;
      if (*ppDVar1) {
        pUnit = 0;
        nServerOrMod = D2Common::Environment::DRLGENV_GetPeriodOfDayFromAct(*ppDVar1, (int32_t*)&pUnit);
        nServerOrMod = D2Common::ITEMS::ItemMods::ITEMMODS_CalculateRepairCost(nByTimeMod, nServerOrMod, (int32_t)pUnit, nullptr, nullptr, nullptr);
        nPercentApplied = Stats::D2ApplyPercent(nArmorClass, nServerOrMod, 100);
        nArmorClass += nPercentApplied;
        if (nServerOrMod) {
          bIsModified = 1;
        }
      }
    }

    uint16_t* pwLabelStr = D2Lang::StrTable::strtable::GetLocaleString(0xd85);
    uint16_t* pwTextAlias = wszText;
    D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszText, pwLabelStr);
    D2Lang::Unicode::UNISYS::AppendToBuffer(pwTextAlias, pwColorPrefix);
    Storm::Source::SSTR::SStrPrintf(szNumBuffer, 10, "%i", nArmorClass);
    D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(local_38, szNumBuffer, 9);
    if (bIsModified) {
      ui::AppendAsWideChar(local_38, 3);
    }

    D2Lang::Unicode::UNISYS::AppendToBuffer(pwTextAlias, local_38);
    D2Lang::Unicode::UNISYS::AppendToBuffer(pwTextAlias, pwColorSuffix);
}

// Appends quantity text to item tooltip for stackable items (arrows, bolts, keys, etc.). Checks item's quantity stat (UNITSTAT_quantity) or max stack size, formats the number, and appends it to the output buffer with proper separators.
static void AppendQuanity(uint16_t * wszText, D2UnitStrc * pUnit) {
    uint16_t wszTempBuffer[10];
    char szPrintfBuffer[12];
    memset(wszTempBuffer, 0, 10 * sizeof(wszTempBuffer[0]));
    uint16_t* pwColorPrefix = D2Lang::StrTable::strtable::GetLocaleString(0xf9b);
    uint16_t* wszText2 = D2Lang::StrTable::strtable::GetLocaleString(0xf9e);
    int nQuantity = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_quantity, 0);
    if (nQuantity <= 0) {
      nQuantity = D2Common::ITEMS::Items::ITEM_GetMaxStack(pUnit);
      if (nQuantity <= 0) {
        return;
      }
    }

    uint16_t* pwQuantityString = D2Lang::StrTable::strtable::GetLocaleString(0xd86);
    D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszText, pwQuantityString);
    nQuantity = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_quantity, 0);
    Storm::Source::SSTR::SStrPrintf(szPrintfBuffer, 10, "%ld", nQuantity);
    D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(wszTempBuffer, szPrintfBuffer, 9);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, pwColorPrefix);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, wszTempBuffer);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, wszText2);
}

