void __stdcall INV_SetShopPageFromNpc(uint8_t bParam) {
    D2UnitStrc* pCarriedItem;
    uint32_t* pTabState;
    uint8_t byNextPage;
    int anPageItemCount[5];
    int32_t nNpcGuid;
    int nCount;
    if (bParam >= 5) {
      bParam = 0;
    }
    if (gnInvShopPage) {
      return;
    }

    BOOL bHasGuid = npcmenu::GetInteractedUnitGuid(&nNpcGuid);
    if (!bHasGuid) {
      return;
    }

    D2UnitStrc* pItem = UNIT::Player::UNITS_FindClientSideUnit(nNpcGuid, UNIT_MONSTER);
    if (!(pItem && pItem->pInventory)) {
      return;
    }

    pItem = D2Common::INVENTORY::Inventory::INVENTORY_GetFirstItem(pItem->pInventory);
    memset(anPageItemCount, 0, 5 * sizeof(anPageItemCount[0]));
    int nTabCount = AmountOfNPCTabs;
    while (true) {
      eInventoryPage ePage;
      AmountOfNPCTabs = nTabCount;
      if (!pItem) {
        break;
      }

      pCarriedItem = D2Common::INVENTORY::Inventory::GetCarriedItem(pItem);
      ePage = D2Common::ITEMS::Items::ITEM_GetContainingInventoryPage(pCarriedItem);
      if (ePage < INVPAGE_Monster) {
        anPageItemCount[ePage]++;
      }

      pItem = D2Common::INVENTORY::Inventory::INVENTORY_GetNextItem(pItem);
      nTabCount = AmountOfNPCTabs;
    }

    int nScanCount = 0;
    uint32_t nNextPage = (uint32_t)bParam;
    int nTabIdx = 0;
    CurrentInventoryPage = bParam;
    if (nTabCount > 0) {
      pTabState = &gaNpcShopTabs[0].nHasItems;
      do {
        nCount = anPageItemCount[nTabIdx];
        pTabState[-1] = 0;
        nTabIdx++;
        *pTabState = (uint32_t)(nCount != 0);
        pTabState = (uint32_t*)((int)pTabState + 0x12);
      } while (nTabIdx < nTabCount);
    }
    if (!anPageItemCount[bParam]) {
      do {
        byNextPage = (char)nNextPage + 1;
        nNextPage = (uint32_t)byNextPage;
        nScanCount++;
        if (byNextPage > TypeOfShopMaybe || byNextPage == 0xff) {
          nNextPage = 0;
        }
      } while (!anPageItemCount[nNextPage] && nScanCount < 4);

      CurrentInventoryPage = (uint8_t)nNextPage;
    }

    gaNpcShopTabs[nNextPage].nSelected = 1;
}

