BOOL __stdcall INV_HandleInventoryLeftClick(D2UIMouseMsgStrc * pMsg) {
    int32_t nMouseY = (int32_t)pMsg->uLParam.sMousePos.nMouseY;
    int32_t nMouseX = (int32_t)pMsg->uLParam.sMousePos.nMouseX;
    gnInvMouseX = nMouseX;
    gpInvCursorItem = nMouseY;
    pMsg->bHandled = 1;
    pMsg->dwResult = 0;
    Storm::SMsgBreakHandlerChain(pMsg);
    if (nMouseX >= pInventoryScreenCoordinates.nLeft && nMouseX < pInventoryScreenCoordinates.nRight && nMouseY >= pInventoryScreenCoordinates.nTop && nMouseY <= pInventoryScreenCoordinates.nBottom) {
      if (nMouseX >= ScreenSizeX - gnPanelOffsetX - 0x12e && nMouseX <= ScreenSizeX - gnPanelOffsetX - 0x10e && nMouseY >= gnPanelOffsetY - 0x60 + ScreenSizeY && nMouseY <= gnPanelOffsetY - 0x40 + ScreenSizeY && gbInvPanelButtonPressed) {
        pMsg->bHandled = 1;
        pMsg->dwResult = 0;
        Storm::SMsgBreakHandlerChain(pMsg);
        ui::thunk_NPCSHOP_IsRepairTabActive();
      }

      gbInvPanelButtonPressed = 0;
      return 1;
    }

    gbInvPanelButtonPressed = 0;
    return 0;
}

BOOL __fastcall INV_HandleInventoryLeftDown(D2UIMouseMsgStrc * pMsg) {
    int32_t nMouseY = (int32_t)pMsg->uLParam.sMousePos.nMouseY;
    uint32_t uVar1 = (uint32_t)pMsg->uLParam.sMousePos.nMouseX;
    pMsg->bHandled = 1;
    pMsg->dwResult = 0;
    Storm::SMsgBreakHandlerChain(pMsg);
    if ((int)uVar1 >= ScreenSizeX - gnPanelOffsetX - 0x12e && (int)uVar1 <= ScreenSizeX - gnPanelOffsetX - 0x10e && nMouseY >= gnPanelOffsetY - 0x60 + ScreenSizeY && nMouseY <= gnPanelOffsetY - 0x40 + ScreenSizeY) {
      gbInvPanelButtonPressed = 1;
      pMsg->bHandled = 1;
      pMsg->dwResult = 0;
      Storm::SMsgBreakHandlerChain(pMsg);
      return 1;
    }

    return 0;
}

// Loads shop tab UI images (invshop1.dc6, invshop2.dc6, invshop3.dc6) from DATA\GLOBAL directory. Constructs file paths using format strings from global text pool and loads DC6 graphics via IMAGE_LoadDC6Ex. Third tab only loads in Expansion mode.
void __stdcall INV_LoadShopTabImages() {
    char szPathBuffer[260];
    if (!UI_GFX) {
      Storm::Source::SSTR::SStrPrintf(szPathBuffer, 0x104, "%s\\ui\\panel\\buyselltabs", "DATA\\GLOBAL");
      UI_GFX = Core::Archive::IMAGE_LoadDC6Ex(szPathBuffer, 0);
    }
    if (!gpInvShopTab1Image) {
      Storm::Source::SSTR::SStrPrintf(szPathBuffer, 0x104, "%s\\ui\\panel\\miniconvert", "DATA\\GLOBAL");
      gpInvShopTab1Image = Core::Archive::IMAGE_LoadDC6Ex(szPathBuffer, 0);
    }
    if (gpInvShopTab2Image) {
      return;
    }

    BOOL bIsExpansion = Fog::D2CheckExpansionGame();
    if (!bIsExpansion) {
      return;
    }

    bIsExpansion = GAME::Game::CLIENT_CheckExpansion();
    if (!bIsExpansion) {
      return;
    }

    Storm::Source::SSTR::SStrPrintf(szPathBuffer, 0x104, "%s\\ui\\panel\\invchar6tab", "DATA\\GLOBAL");
    gpInvShopTab2Image = Core::Archive::IMAGE_LoadDC6Ex(szPathBuffer, 0);
}

void __stdcall INV_FreeShopTabImages() {
    if (gpInvShopTabImage) {
      Core::Archive::DC6_FreeAndDelete(gpInvShopTabImage);
      gpInvShopTabImage = 0;
    }
    if (UI_GFX) {
      Core::Archive::DC6_FreeAndDelete(UI_GFX);
      UI_GFX = 0;
    }
    if (gpInvShopTab1Image) {
      Core::Archive::DC6_FreeAndDelete(gpInvShopTab1Image);
      gpInvShopTab1Image = 0;
    }

    BOOL bIsExpansion = GAME::Game::CLIENT_CheckExpansion();
    if (!(bIsExpansion && gpInvShopTab2Image)) {
      return;
    }

    Core::Archive::DC6_FreeAndDelete(gpInvShopTab2Image);
    gpInvShopTab2Image = 0;
}

// Initializes trade mode UI. Clears gbInventoryDragInProgress flag, sets up trade window inventory grids, loads partner inventory data. Called when trade UI opens.
void __fastcall INV_InitTradeMode(int32_t nParam) {
    if (gbInvTradeWindowOpen || gbInvTradeWindowOpen2) {
      Sound::SOUND_PlaySound(SOUND_CURSOR_ERROR, nullptr, 0, 0, 0);
    }

    gbInvTradeWindowOpen = 0;
    gbInvTradeWindowOpen2 = 0;
    gnInvInventoryGold = 0;
    if (nParam) {
      char szPathBuf[260];
      gdwInvLastActionTickCount = 0;
      g_nCurrentInventoryPage = 0xb;
      Path::TypeOfUiOverlayOverWorld(3);
      if (!gpInvShopTabImage) {
        Storm::Source::SSTR::SStrPrintf(szPathBuf, 0x104, "%s\\ui\\panel\\trade", "DATA\\GLOBAL");
        gpInvShopTabImage = Core::Archive::IMAGE_LoadDC6Ex(szPathBuf, 0);
      }
    } else {
      g_nCurrentInventoryPage = 10;
      Path::TypeOfUiOverlayOverWorld(0);
    }

    gShopTradeUIState = 0;
    gbTradeConfirmationPending = 0;
    gbInvTradeAcceptClicked = 0;
    gbInventoryDragInProgress = 0;
    gbInvTradeCancelClicked = 0;
}

