// Handles left-click in trade window. Sets/clears gbInventoryDragInProgress based on cursor state. Picks up item from trade grid or places item, sends trade update packet to partner.
void __stdcall INV_HandleTradeLeftClick(D2UIMouseMsgStrc * pMsg) {
    if (g_nCurrentInventoryPage != 0xb) {
      gShopTradeUIState = 0;
      return;
    }

    int32_t nMouseY;
    nMouseY = (int32_t)pMsg->uLParam.sMousePos.nMouseY;
    int32_t nMouseX;
    nMouseX = (int32_t)pMsg->uLParam.sMousePos.nMouseX;
    gnInvMouseX = nMouseX;
    gpInvCursorItem = nMouseY;
    gbInvPanelButtonPressed = 0;
    gnInvMouseY = 0;
    D2UnitStrc* pCursorItem_lcl;
    pCursorItem_lcl = UNIT::Player::GetPlayerUnit_UI();
    BOOL nBodyLoc;
    nBodyLoc = Panel::PANEL_CalculateBeltSlotIndex(pMsg);
    if (!nBodyLoc) {
      D2InventoryStrc* pTradeInventory = pCursorItem_lcl->pInventory;
      pCursorItem_lcl = D2Common::INVENTORY::Inventory::INVENTORY_GetHandItem(pTradeInventory);
      if (!pCursorItem_lcl) {
        nBodyLoc = INV_IsMouseOverCloseButton(nMouseX, nMouseY);
        if (nBodyLoc) {
          Trade::TRADE_CloseTrade();
          return;
        }
      }
    }
    if (nMouseX > pTradePage2GridScreenCoordinates.nPixelLeft && nMouseX < pTradePage2GridScreenCoordinates.nRight && nMouseY >= pTradePage2GridScreenCoordinates.nTop && nMouseY <= pTradePage2GridScreenCoordinates.nBottom) {
      consume_and_reset_trade:
      pMsg->bHandled = 1;
      pMsg->dwResult = 0;
      Storm::SMsgBreakHandlerChain(pMsg);
      if (gbTradeConfirmationPending) {
        Trade::CancelTrade();
      }

      gShopTradeUIState = 0;
      gbInvTradeAcceptClicked = 0;
      gbTradeConfirmationPending = 0;
      return;
    }

    nBodyLoc = INV_IsMouseOverAcceptTradeBtn(nMouseY, nMouseX);
    if (nBodyLoc) {
      if (gbTradeConfirmationPending && gbInventoryDragInProgress) {
        Trade::AcceptTrade();
      }

      gShopTradeUIState = 0;
    } else {
      nBodyLoc = INV_IsMouseOverCancelTradeBtn(nMouseY, nMouseX);
      if (nBodyLoc) {
        if (gbInvTradeAcceptClicked && gbInvTradeCancelClicked) {
          Trade::TRADE_CloseTrade();
          gbInvTradeAcceptClicked = 0;
        }

        gbInvTradeCancelClicked = 0;
        gShopTradeUIState = 0;
        goto consume_message;
      }

      nBodyLoc = Panel::PANEL_CalculateBeltSlotIndex(pMsg);
      if (nBodyLoc == 1) {
        gbInventoryDragInProgress = 0;
        gbTradeConfirmationPending = 0;
        gShopTradeUIState = 0;
        gbInvTradeAcceptClicked = 0;
        return;
      }

      nBodyLoc = INV_IsMouseOverGoldButton(nMouseX, nMouseY);
      if (nBodyLoc && !gbInvGoldDialogOpen) {
        ui::UI_ShowGoldTransactionDialog(2);
      }
      if (!gShopTradeUIState) {
        goto consume_and_reset_trade;
      }

      gShopTradeUIState = 0;
      if (gbInventoryDragInProgress) {
        if (gbTradeConfirmationPending == 1) {
          gbTradeConfirmationPending = 0;
          Trade::CancelTrade();
        }
      } else {
        if (gbInvTradeCancelClicked && gbInvTradeAcceptClicked) {
          gbInvTradeAcceptClicked = 0;
        }
      }

      gbInvTradeCancelClicked = 0;
    }

    gbInventoryDragInProgress = 0;
    consume_message:
    pMsg->bHandled = 1;
    pMsg->dwResult = 0;
    Storm::SMsgBreakHandlerChain(pMsg);
}

