static BOOL INV_IsMouseOverStashCloseBtn(int32_t nMouseX, int32_t nMouseY) {
    int nBottomY;
    BOOL bIsExpansion = GAME::Game::CLIENT_CheckExpansion();
    if (bIsExpansion) {
      if (nMouseY < gnPanelOffsetY - 0x1c7 + ScreenSizeY) {
        return 0;
      }

      nBottomY = gnPanelOffsetY - 0x1b6;
    } else {
      if (nMouseY < gnPanelOffsetY - 0x103 + ScreenSizeY) {
        return 0;
      }

      nBottomY = gnPanelOffsetY - 0xf2;
    }
    if (!(nMouseY <= nBottomY + ScreenSizeY && nMouseX >= gnPanelOffsetX + 0x49 && nMouseX <= gnPanelOffsetX + 0x96)) {
      return 0;
    }

    return 1;
}

static BOOL INV_IsMouseOverStashGoldBtn(int32_t nMouseY, int32_t nMouseX) {
    int nBtnBound;
    BOOL bIsExpansion = GAME::Game::CLIENT_CheckExpansion();
    if (!bIsExpansion) {
      nBtnBound = gnPanelOffsetX + 0x113;
    } else {
      nBtnBound = gnPanelOffsetX + 0x110;
    }
    if (nMouseX <= nBtnBound) {
      return 0;
    }

    bIsExpansion = GAME::Game::CLIENT_CheckExpansion();
    if (!bIsExpansion) {
      nBtnBound = gnPanelOffsetX + 0x113;
    } else {
      nBtnBound = gnPanelOffsetX + 0x110;
    }
    if (!(nMouseX < nBtnBound + 0x28)) {
      return 0;
    }

    bIsExpansion = GAME::Game::CLIENT_CheckExpansion();
    if (!bIsExpansion) {
      nBtnBound = gnPanelOffsetY - 0x41;
    } else {
      nBtnBound = gnPanelOffsetY - 0x40;
    }
    if (!(nMouseY > nBtnBound + ScreenSizeY - 0x23)) {
      return 0;
    }

    int32_t nGoldButtonY = INV_GetGoldButtonY();
    if (nMouseY < nGoldButtonY + 5) {
      return 1;
    }

    return 0;
}

void __stdcall INV_HandleStashMouseMove(D2UIMouseMsgStrc * pMsg) {
    if (!(g_nCurrentInventoryPage == 0xc || g_nCurrentInventoryPage == 0xd)) {
      return;
    }

    gnInvMouseX = (int)pMsg->uLParam.sMousePos.nMouseX;
    gpInvCursorItem = (uint32_t)pMsg->uLParam.sMousePos.nMouseY;
    if (gnInvMouseX < pInventoryScreenCoordinates.nLeft || gnInvMouseX >= pInventoryScreenCoordinates.nRight || (int)gpInvCursorItem < pInventoryScreenCoordinates.nTop || (int)gpInvCursorItem > pInventoryScreenCoordinates.nBottom) {
      D2UnitStrc* pBankRangeResult;
      pBankRangeResult = (D2UnitStrc*)IsInBankPageScreenRange(gnInvMouseX, gpInvCursorItem);
      if (!pBankRangeResult) {
        gpInvItemUnderCursor = (uint32_t)(uintptr_t)pBankRangeResult;
        gbInvBodySlotUnderCursorExists = (uint32_t)(uintptr_t)pBankRangeResult;
        pItemToDescribe = pBankRangeResult;
        gpInvHoveredItem = pBankRangeResult;
        D2Win::Src::D2WinFont::TEXT_TooltipSetAttributes(nullptr, -1, -1, 0, 0);
        return;
      }
    }

    INV_HandleMouseMove(pMsg);
}

// Handles left-click in stash window. Sets/clears gbInventoryDragInProgress based on cursor state. Picks up item from stash grid or places item, sends stash update packet to server.
void __stdcall INV_HandleStashLeftClick(D2UIMouseMsgStrc * pMsg) {
    BOOL nHitTest;
    if (g_nCurrentInventoryPage != 0xc && g_nCurrentInventoryPage != 0xd) {
      gShopTradeUIState = 0;
      return;
    }

    uint32_t uMouseX;
    uMouseX = (uint32_t)pMsg->uLParam.sMousePos.nMouseX;
    uint32_t uMouseY;
    uMouseY = (uint32_t)pMsg->uLParam.sMousePos.nMouseY;
    gbInvPanelButtonPressed = 0;
    gnInvMouseY = 0;
    gnInvMouseX = uMouseX;
    gpInvCursorItem = uMouseY;
    D2UnitStrc* pPlayerOrCursorItem;
    pPlayerOrCursorItem = UNIT::Player::GetPlayerUnit_UI();
    D2InventoryStrc* pInventory;
    pInventory = pPlayerOrCursorItem->pInventory;
    uint32_t bHoverFlag;
    bHoverFlag = Panel::PANEL_GetBeltSlotHoverFlag();
    if (bHoverFlag) {
      nHitTest = Panel::PANEL_CalculateBeltSlotIndex(pMsg);
      if (nHitTest) {
        goto test_stash_buttons;
      }
    }

    pPlayerOrCursorItem = D2Common::INVENTORY::Inventory::INVENTORY_GetHandItem(pInventory);
    if (!pPlayerOrCursorItem) {
      nHitTest = INV_IsMouseOverCloseButton(uMouseX, uMouseY);
      if (nHitTest) {
        ui::SetUIFlag(UI_STASH, UI_RESET, 0);
        return;
      }
    }

    test_stash_buttons:
    nHitTest = INV_IsMouseOverStashGoldBtn(uMouseY, uMouseX);
    if (nHitTest) {
      if (gbInvStashPageOpen) {
        gbInvStashPageOpen = 0;
        ui::SetUIFlag(UI_STASH, UI_RESET, 0);
        GAME::Msg::NET_D2GS_CLIENT_Send_SHORT_SHORT_SHORT(0x4f, 0x12, 0, 0);
      }

      gbInvStashDepositClicked = 0;
      gShopTradeUIState = 0;
      pMsg->bHandled = 1;
      pMsg->dwResult = 0;
      Storm::SMsgBreakHandlerChain(pMsg);
      return;
    }

    gbInvStashPageOpen = 0;
    gbInvStashDepositClicked = 0;
    bHoverFlag = Panel::PANEL_GetBeltSlotHoverFlag();
    if (!bHoverFlag) {
      nHitTest = INV_IsMouseOverGoldButton(uMouseX, uMouseY);
      if (nHitTest && !gbInvGoldDialogOpen) {
        ui::UI_ShowGoldTransactionDialog(3);
      }
    }

    nHitTest = INV_IsMouseOverStashCloseBtn(uMouseX, uMouseY);
    if (nHitTest && !gbInvGoldDialogOpen) {
      ui::UI_ShowGoldTransactionDialog(4);
    }

    nHitTest = Panel::PANEL_CalculateBeltSlotIndex(pMsg);
    if (nHitTest == 1) {
      gbInventoryDragInProgress = 0;
      gbInvStashDepositClicked = 0;
      return;
    }

    gnInvStashGold = 0;
    gnInvInventoryGold = 0;
    if (gShopTradeUIState) {
      gShopTradeUIState = 0;
      if (gbInventoryDragInProgress) {
        if (gbTradeConfirmationPending == 1) {
          gbTradeConfirmationPending = 0;
        }
      } else {
        if (gbInvStashDepositClicked && gbInvStashPageOpen) {
          gbInvStashPageOpen = 0;
        }
      }

      gbInventoryDragInProgress = 0;
      gbInvStashDepositClicked = 0;
      pMsg->bHandled = 1;
      pMsg->dwResult = 0;
      Storm::SMsgBreakHandlerChain(pMsg);
      return;
    }

    pMsg->bHandled = 1;
    pMsg->dwResult = 0;
    Storm::SMsgBreakHandlerChain(pMsg);
    gShopTradeUIState = 0;
    gbInvStashPageOpen = 0;
    gbTradeConfirmationPending = 0;
}

