void __fastcall INV_StartCubeTransmuteAnim(int32_t nMenuActionId) {
    BOOL bAlreadyDone;
    char szPathBuffer[260];
    eD2Quests nQuestId;
    D2BitBufferStrc* pBitBuffer;
    pBitBuffer = npcmenu::GetQuestInfo();
    if (nMenuActionId == 0x20747368) {
      if (!pBitBuffer) {
        return;
      }

      bAlreadyDone = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_TheHoradricStaff, QUESTSTATE_Step0x11);
      if (bAlreadyDone) {
        return;
      }

      nQuestId = QUEST_TheHoradricStaff;
    } else {
      if (nMenuActionId != 0x20326671) {
        goto start_anim;
      }
      if (!pBitBuffer) {
        return;
      }

      bAlreadyDone = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_KhalimsWill, QUESTSTATE_Step0x11);
      if (bAlreadyDone) {
        return;
      }

      nQuestId = QUEST_KhalimsWill;
    }

    D2Common::QuestRecord::SetQuestState(pBitBuffer, nQuestId, QUESTSTATE_Step0x11);
    start_anim:
    gpInvCubeImage1 = 1;
    gpInvCubeImage2 = 0;
    gpInvCubeImage3 = GetTickCount();
    if (gpInvCubeImage4) {
      return;
    }

    Storm::Source::SSTR::SStrPrintf(szPathBuffer, 0x104, "%s\\ui\\menu\\horadric", "DATA\\GLOBAL");
    gpInvCubeImage4 = Core::Archive::IMAGE_LoadDC6Ex(szPathBuffer, 0);
}

