void __stdcall INV_SwapWeaponSet() {
    BOOL bIsExpansion = Fog::D2CheckExpansionGame();
    if (!bIsExpansion) {
      return;
    }

    bIsExpansion = GAME::Game::CLIENT_CheckExpansion();
    if (!bIsExpansion) {
      return;
    }

    Sound::SOUND_PlaySound(SOUND_CURSOR_PASS, nullptr, 0, 0, 0);
    GAME::Msg::NET_D2GS_CLIENT_Send_CMD(0x60);
    D2UnitStrc* pWeaponItem = UNIT::Player::GetPlayerUnit_UI();
    D2InventoryStrc* pInventory = pWeaponItem->pInventory;
    pWeaponItem = D2Common::INVENTORY::Inventory::INVENTORY_GetItemByGridOffset(pInventory, 4);
    if (pWeaponItem) {
      UNIT::ITEM_RemoveClientSide(pWeaponItem);
    }

    pWeaponItem = D2Common::INVENTORY::Inventory::INVENTORY_GetItemByGridOffset(pInventory, 5);
    if (!pWeaponItem) {
      return;
    }

    UNIT::ITEM_RemoveClientSide(pWeaponItem);
}

